define({"topics":[{"title":"Installing host system software","shortdesc":"<p class=\"shortdesc\">This quick start guide provides an overview of the procedures required to load host system software. Refer to the tasks included within this procedure for detailed information.<\/p>","href":"r_InstallingHostSystemSoftware.html","attributes":{"data-id":"id_2003115"},"menu":{"hasChildren":true},"tocID":"id_2003115-d46e5150","next":"id_2003115-d46e5150"},{"title":"Installing service packs","shortdesc":"<p class=\"shortdesc\">When GE releases new software versions, it may be necessary to install updates to a host PC. <\/p>","href":"t_InstallingServicePacks.html","attributes":{"data-id":"id_2002881"},"menu":{"hasChildren":true},"tocID":"id_2002881-d46e6403","next":"id_2002881-d46e6403"},{"title":"Installing updates from Remote Software Download (RSD)","shortdesc":"<p class=\"shortdesc\">RSD is an installer application that helps to install new updates from service packs whenever they are released and pushed from the GE back office. <\/p>","href":"t_InstallingUpdatesFromRemoteSoftwareDownload.html","attributes":{"data-id":"id_2001525"},"menu":{"hasChildren":true},"tocID":"id_2001525-d46e6602","next":"id_2001525-d46e6602"}]});